      es: ["Área protegida desde 2002.", "Superficie: 1,5 km².", "Cobertura de coral: originalmente 50%, hoy reducida por daños.", "Número de especies de peces: más de 60.", "Buceadores por año: aprox. 100.000.", "Temperatura de la superficie del agua: 27-30°C."],
      pt: ["Área protegida desde 2002.", "Superfície: 1,5 km².", "Cobertura de coral: originalmente 50%, hoje reduzida por danos.", "Número de espécies de peixes: mais de 60.", "Mergulhadores por ano: aprox. 100.000.", "Temperatura da superfície da água: 27-30°C."],
      fr: ["Zone protégée depuis 2002.", "Superficie : 1,5 km².", "Couverture corallienne : initialement 50 %, aujourd'hui réduite par les dommages.", "Nombre d'espèces de poissons : plus de 60.", "Plongeurs par an : env. 100 000.", "Température de la surface de l'eau : 27-30°C."],
