      es: ["Fundada en 1885.", "Altitud: 1.800 m.", "Superficie de cultivo: aprox. 200 hectáreas.", "Producción anual: aprox. 500 toneladas.", "Empleados: aprox. 500 trabajadores.", "Producción de té CTC desde 1950."],
      pt: ["Fundada em 1885.", "Altitude: 1.800 m.", "Área de cultivo: aprox. 200 hectares.", "Produção anual: aprox. 500 toneladas.", "Funcionários: aprox. 500 trabalhadores.", "Produção de chá CTC desde 1950."],
